    int n;
    if (!(cin >> n)) return 0;

    vector<Range> ranges(n);
    for (int i = 0; i < n; ++i) {
        cin >> ranges[i].first >> ranges[i].second;
        if (ranges[i].first > ranges[i].second) {
            cout << "INVALID\n";
            return 0;
        }
