    sort(ranges.begin(), ranges.end());

    vector<Range> merged;
    for (const auto& [l, r] : ranges) {
        if (merged.empty() || merged.back().second < l - 1) {
            merged.emplace_back(l, r);
        } else {
            merged.back().second = max(merged.back().second, r);
        }
    }

    cout << merged.size() << '\n';
    for (const auto& [l, r] : merged) {
        cout << l << ' ' << r << '\n';
    }

    return 0;
}
