#include <deque>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (k <= 0 || k > n) {
        cout << "INVALID\n";
        return 0;
    }

    int64_t sum = 0;
    for (int i = 0; i < k; ++i) sum += a[i];

    deque<int> min_q, max_q;
    for (int i = 0; i < k; ++i) {
        while (!min_q.empty() && a[min_q.back()] >= a[i]) min_q.pop_back();
        min_q.push_back(i);
        while (!max_q.empty() && a[max_q.back()] <= a[i]) max_q.pop_back();
        max_q.push_back(i);
    }

    for (int left = 0; left <= n - k; ++left) {
        cout << sum << ' ' << a[min_q.front()] << ' ' << a[max_q.front()] << '\n';
        if (left + k < n) {
            sum -= a[left];
            sum += a[left + k];
            int new_idx = left + k;
            while (!min_q.empty() && min_q.front() <= left) min_q.pop_front();
            while (!max_q.empty() && max_q.front() <= left) max_q.pop_front();
            while (!min_q.empty() && a[min_q.back()] >= a[new_idx]) min_q.pop_back();
            min_q.push_back(new_idx);
            while (!max_q.empty() && a[max_q.back()] <= a[new_idx]) max_q.pop_back();
            max_q.push_back(new_idx);
        }
    }
    return 0;
}
