#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;

const long long MOD = 1000000007LL;

long long mod_normalize(long long x) {
    return ((x % MOD) + MOD) % MOD;
}

class LazySegmentTree {
private:
    int n;
    vector<long long> tree;
    vector<long long> lazy_mul;
    vector<long long> lazy_add;

    void build(const vector<long long>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = mod_normalize(arr[start]);
            lazy_mul[node] = 1;
            lazy_add[node] = 0;
            return;
        }
        int mid = (start + end) / 2;
        build(arr, 2*node+1, start, mid);
        build(arr, 2*node+2, mid+1, end);
        tree[node] = (tree[2*node+1] + tree[2*node+2]) % MOD;
        lazy_mul[node] = 1;
        lazy_add[node] = 0;
    }

    void apply(int node, int start, int end, long long mul, long long add) {
        tree[node] = (tree[node] * mul + add * (end - start + 1)) % MOD;
        lazy_mul[node] = (lazy_mul[node] * mul) % MOD;
        lazy_add[node] = (lazy_add[node] * mul + add) % MOD;
    }

    void push(int node, int start, int end) {
        if (lazy_mul[node] != 1 || lazy_add[node] != 0) {
            int mid = (start + end) / 2;
            apply(2*node+1, start, mid, lazy_mul[node], lazy_add[node]);
            apply(2*node+2, mid+1, end, lazy_mul[node], lazy_add[node]);
            lazy_mul[node] = 1;
            lazy_add[node] = 0;
        }
    }

    void update_range(int node, int start, int end, int l, int r, long long mul, long long add) {
        if (r < start || end < l) return;
        if (l <= start && end <= r) {
            apply(node, start, end, mul, add);
            return;
        }
        push(node, start, end);
        int mid = (start + end) / 2;
        update_range(2*node+1, start, mid, l, r, mul, add);
        update_range(2*node+2, mid+1, end, l, r, mul, add);
        tree[node] = (tree[2*node+1] + tree[2*node+2]) % MOD;
    }

    long long query_range(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return tree[node];
        push(node, start, end);
        int mid = (start + end) / 2;
        long long left_sum = query_range(2*node+1, start, mid, l, r);
        long long right_sum = query_range(2*node+2, mid+1, end, l, r);
        return (left_sum + right_sum) % MOD;
    }

public:
    LazySegmentTree(const vector<long long>& arr) {
        n = arr.size();
        tree.resize(4*n);
        lazy_mul.resize(4*n, 1);
        lazy_add.resize(4*n, 0);
        build(arr, 0, 0, n-1);
    }

    void add_range(int l, int r, long long x) {
        update_range(0, 0, n-1, l, r, 1, mod_normalize(x));
    }

    void mul_range(int l, int r, long long x) {
        update_range(0, 0, n-1, l, r, mod_normalize(x), 0);
    }

    long long sum_range(int l, int r) {
        return query_range(0, 0, n-1, l, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
        arr[i] = mod_normalize(arr[i]);
    }

    LazySegmentTree segtree(arr);

    for (int i = 0; i < q; ++i) {
        string type;
        cin >> type;
        if (type == "ADD") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            segtree.add_range(l, r, x);
        } else if (type == "MUL") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            segtree.mul_range(l, r, x);
        } else if (type == "SUM") {
            int l, r;
            cin >> l >> r;
            long long res = segtree.sum_range(l, r);
            cout << res << '\n';
        }
    }

    return 0;
}
