    def get(self, key):
        entry = self._store.get(key)
        if entry is None:
            raise KeyError(key)
        value, expires_at = entry
        if self._clock() >= expires_at:
            del self._store[key]
            raise KeyError(key)
        return value

    def delete(self, key):
        return self._store.pop(key, None) is not None
