#include <cstdio>
#include <vector>
#include <algorithm>

struct Range {
    int64_t l;
    int64_t r;
};

int main() {
    int n;
    if (std::scanf("%d", &n) != 1) {
        return 0;
    }

    std::vector<Range> ranges;
    ranges.reserve(n);

    for (int i = 0; i < n; ++i) {
        int64_t l, r;
        if (std::scanf("%lld %lld", &l, &r) != 2) {
            return 0;
        }
        if (l > r) {
            std::printf("INVALID\n");
            return 0;
        }
        ranges.push_back({l, r});
    }

    if (n == 0) {
        std::printf("0\n");
        return 0;
    }

    std::sort(ranges.begin(), ranges.end(),
              [](const Range& a, const Range& b) {
                  if (a.l != b.l) return a.l < b.l;
                  return a.r < b.r;
              });

    // Merge using overflow-safe adjacency check.
    // Two ranges [cl, cr] and [nl, nr] merge when nl <= cr + 1.
    // To avoid evaluating cr + 1 when cr == INT64_MAX, we check
    //   nl == INT64_MIN  ||  nl <= cr + 1
    // which is equivalent to nl <= cr + 1 for all valid int64_t nl.
    Range merged = ranges[0];
    int m = 1;

    for (int i = 1; i < n; ++i) {
        const Range& cur = ranges[i];
        if (cur.l == std::INT64_MIN || cur.l <= merged.r + 1) {
            if (cur.r > merged.r) {
                merged.r = cur.r;
            }
        } else {
            ranges[m++] = merged;
            merged = cur;
        }
    }
    ranges[m++] = merged;

    std::printf("%d\n", m);
    for (int i = 0; i < m; ++i) {
        std::printf("%lld %lld\n", ranges[i].l, ranges[i].r);
    }

    return 0;
}
```

**Overflow-safety rationale:**

The naive check `cur.l <= merged.r + 1` would overflow when `merged.r == INT64_MAX`. The code instead uses the equivalent condition:

```
cur.l == INT64_MIN || cur.l <= merged.r + 1
```

This is logically identical to `cur.l <= merged.r + 1` for every valid `int64_t` value of `cur.l`, because:
- If `cur.l == INT64_MIN`, then `cur.l <= merged.r + 1` is always true (since `merged.r + 1 <= INT64_MAX` whenever it's representable, and `INT64_MIN` is less than any such value).
- Otherwise, `merged.r + 1` is well-defined (no overflow), so the comparison behaves exactly as intended.

This correctly handles the boundary case where `merged.r == INT64_MAX` and `cur.l == INT64_MIN` (they merge), while never performing an out-of-range addition.

