    // To avoid evaluating cr + 1 when cr == INT64_MAX, we check
    //   nl == INT64_MIN  ||  nl <= cr + 1
    // which is equivalent to nl <= cr + 1 for all valid int64_t nl.
    Range merged = ranges[0];
    int m = 1;

    for (int i = 1; i < n; ++i) {
        const Range& cur = ranges[i];
        if (cur.l == std::INT64_MIN || cur.l <= merged.r + 1) {
            if (cur.r > merged.r) {
                merged.r = cur.r;
            }
        } else {
            ranges[m++] = merged;
            merged = cur;
        }
    }
    ranges[m++] = merged;

    std::printf("%d\n", m);
    for (int i = 0; i < m; ++i) {
        std::printf("%lld %lld\n", ranges[i].l, ranges[i].r);
    }

    return 0;
