int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (k <= 0 || k > n) {
        cout << "INVALID\n";
        return 0;
    }

    // Running sum of the current window, computed in 64-bit to avoid overflow.
    int64_t sum = 0;
    for (int i = 0; i < k; ++i) sum += a[i];

    // Monotonic deques storing indices; front is always the window's min/max.
    deque<int> minq, maxq;
    for (int i = 0; i < k; ++i) {
        while (!minq.empty() && a[minq.back()] >= a[i]) minq.pop_back();
        while (!maxq.empty() && a[maxq.back()] <= a[i]) maxq.pop_back();
        minq.push_back(i);
        maxq.push_back(i);
    }

    for (int i = k; i < n; ++i) {
        // Remove elements that have slid out of the window.
        if (minq.front() <= i - k) minq.pop_front();
        if (maxq.front() <= i - k) maxq.pop_front();

        // Maintain monotonicity with the newly added element.
        while (!minq.empty() && a[minq.back()] >= a[i]) minq.pop_back();
        while (!maxq.empty() && a[maxq.back()] <= a[i]) maxq.pop_back();
        minq.push_back(i);
        maxq.push_back(i);

        sum += a[i];
        sum -= a[i - k];

        cout << sum << ' ' << a[minq.front()] << ' ' << a[maxq.front()] << '\n';
    }

    return 0;
}
