#include <bits/stdc++.h>
using namespace std;

static constexpr long long M = 1000000007LL;

// Modular arithmetic helpers
static inline long long mod(long long x) {
    x %= M;
    if (x < 0) x += M;
    return x;
}
static inline long long mul(long long a, long long b) {
    return mod(a) * mod(b) % M;
}

// Segment tree with lazy propagation for range affine updates (v -> v*mul + add)
// and range sum queries, all modulo M.
struct SegTree {
    int n;
    vector<long long> sum;   // sum[i] = sum of leaves in node i's range
    vector<long long> mul;   // lazy multiplier
    vector<long long> add;   // lazy adder
    vector<long long> init;  // original values (for building)

    SegTree(const vector<long long>& a) {
        n = (int)a.size();
        sum.assign(4 * n, 0);
        mul.assign(4 * n, 1);
        add.assign(4 * n, 0);
        init = a;
        build(1, 0, n - 1);
    }

    void build(int node, int lo, int hi) {
        if (lo == hi) {
            sum[node] = mod(init[lo]);
            return;
        }
        int mid = (lo + hi) >> 1;
        build(node << 1, lo, mid);
        build(node << 1 | 1, mid + 1, hi);
        sum[node] = sum[node << 1] + sum[node << 1 | 1];
        if (sum[node] >= M) sum[node] -= M;
    }

    // Apply operation (m, a): v -> v*m + a, to node covering [lo, hi]
    void apply(int node, int lo, int hi, long long m, long long a) {
        sum[node] = mul(m, sum[node]) + a;
        if (sum[node] >= M) sum[node] -= M;
        mul[node] = mul(mul[node], m);
        add[node] = mul(add[node], m) + a;
        if (add[node] >= M) add[node] -= M;
    }

    void push(int node, int lo, int hi) {
        if (mul[node] == 1 && add[node] == 0) return;
        int mid = (lo + hi) >> 1;
        apply(node << 1, lo, mid, mul[node], add[node]);
        apply(node << 1 | 1, mid + 1, hi, mul[node], add[node]);
        mul[node] = 1;
        add[node] = 0;
    }

    void update(int node, int lo, int hi, int ql, int qr, long long m, long long a) {
        if (qr < lo || hi < ql) return;
        if (ql <= lo && hi <= qr) {
            apply(node, lo, hi, m, a);
            return;
        }
        push(node, lo, hi);
        int mid = (lo + hi) >> 1;
        update(node << 1, lo, mid, ql, qr, m, a);
        update(node << 1 | 1, mid + 1, hi, ql, qr, m, a);
        sum[node] = sum[node << 1] + sum[node << 1 | 1];
        if (sum[node] >= M) sum[node] -= M;
    }

    long long query(int node, int lo, int hi, int ql, int qr) {
        if (qr < lo || hi < ql) return 0;
        if (ql <= lo && hi <= qr) return sum[node];
        push(node, lo, hi);
        int mid = (lo + hi) >> 1;
        long long left = query(node << 1, lo, mid, ql, qr);
        long long right = query(node << 1 | 1, mid + 1, hi, ql, qr);
        return left + right;
    }

    // Public API
    void add(int l, int r, long long x) {
        update(1, 0, n - 1, l, r, 1, mod(x));
    }
    void mul(int l, int r, long long x) {
        update(1, 0, n - 1, l, r, mod(x), 0);
    }
    long long sum(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        a[i] = mod(a[i]);
    }

    SegTree st(a);

    string op;
    for (int i = 0; i < q; ++i) {
        cin >> op;
        if (op == "ADD") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            st.add(l, r, x);
        } else if (op == "MUL") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            st.mul(l, r, x);
        } else if (op == "SUM") {
            int l, r;
            cin >> l >> r;
            cout << st.sum(l, r) << '\n';
        }
    }

    return 0;
}
