def resolve_order(graph):
    # Build the set of all nodes
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        for dep in deps:
            all_nodes.add(dep)

    # Build adjacency: for each node, its dependencies (edges dep -> node)
    # We need to track in-degree: number of dependencies not yet emitted
    # Actually, let's think: a node is eligible when all its dependencies have been emitted.
    # So for each node, we need to know how many of its dependencies are still pending.

    # Build a map from node to its dependencies (as a set to handle duplicates)
    node_deps = {}
    for node, deps in graph.items():
        node_deps[node] = set(deps)

    # Nodes not in graph keys but in dependencies have no dependencies of their own
    for node in all_nodes:
        if node not in node_deps:
            node_deps[node] = set()

    # Compute in-degree: for each node, the number of dependencies
    # Actually, we need to track how many dependencies are still "unresolved"
    # Let's use a different approach: 
    # For each node, count how many of its dependencies are still pending.
    # Initially, pending_count[node] = len(node_deps[node])

    pending_count = {}
    for node in all_nodes:
        pending_count[node] = len(node_deps[node])

    # We also need to know, for each dependency, which nodes depend on it
    # So when a dependency is emitted, we decrement pending_count for all nodes that depend on it
    dep_to_dependents = {}
    for node in all_nodes:
        for dep in node_deps[node]:
            if dep not in dep_to_dependents:
                dep_to_dependents[dep] = []
            dep_to_dependents[dep].append(node)

    # Initialize the set of eligible nodes (pending_count == 0)
    eligible = set()
    for node in all_nodes:
        if pending_count[node] == 0:
            eligible.add(node)

    result = []
    emitted = set()

    while eligible:
        # Choose lexicographically smallest
        node = min(eligible)
        result.append(node)
        emitted.add(node)
        eligible.remove(node)

        # For each node that depends on this node, decrement pending_count
        if node in dep_to_dependents:
            for dependent in dep_to_dependents[node]:
                pending_count[dependent] -= 1
                if pending_count[dependent] == 0:
                    eligible.add(dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")

    return result
