#include <algorithm>
#include <cstdint>

int main() {
    int n;
    std::cin >> n;

    std::vector<std::pair<int64_t, int64_t>> ranges;
    ranges.reserve(n);

    for (int i = 0; i < n; ++i) {
        int64_t l, r;
        std::cin >> l >> r;
        if (l > r) {
            std::cout << "INVALID\n";
            return 0;
        }
        ranges.emplace_back(l, r);
    }

    // Sort by start, then by end
    std::sort(ranges.begin(), ranges.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Merge overlapping or adjacent ranges
    std::vector<std::pair<int64_t, int64_t>> merged;
    if (!ranges.empty()) {
        int64_t cur_l = ranges[0].first;
        int64_t cur_r = ranges[0].second;

        for (size_t i = 1; i < ranges.size(); ++i) {
            int64_t l = ranges[i].first;
            int64_t r = ranges[i].second;

            // Check if [l, r] overlaps or is adjacent to [cur_l, cur_r]
            // Adjacent means l == cur_r + 1, but we must avoid overflow.
            // Instead, check: l <= cur_r + 1  <=>  l - 1 <= cur_r
            // But l - 1 can underflow if l == INT64_MIN.
            // Better: check if l <= cur_r + 1 without computing cur_r + 1.
            // We can check: l <= cur_r + 1  is equivalent to:
            //   if cur_r == INT64_MAX, then any l <= INT64_MAX is true (since l is int64_t)
            //   otherwise, l <= cur_r + 1
            // Alternatively: l <= cur_r + 1  <=>  l - 1 <= cur_r
            // But l - 1 underflows if l == INT64_MIN.
            //
            // Safer approach:
            // Two ranges [a, b] and [c, d] overlap or are adjacent if c <= b + 1.
            // To avoid overflow:
            //   if b == INT64_MAX, then b + 1 overflows, but any c <= INT64_MAX is true.
            //   else, check c <= b + 1.
            //
            // Another way: c <= b + 1  <=>  c - 1 <= b
            // But c - 1 underflows if c == INT64_MIN.
            //
            // Let's use:
            //   if cur_r == INT64_MAX, then they always overlap/adjacent (since l <= INT64_MAX always)
            //   else, check l <= cur_r + 1
            //
            // But wait: if cur_r == INT64_MAX, then cur_r + 1 overflows. But since l is at most INT64_MAX, l <= INT64_MAX is always true, so they merge.
            // If cur_r < INT64_MAX, then cur_r + 1 is safe.

            bool should_merge;
            if (cur_r == INT64_MAX) {
